const b = $input.first().json.body || $input.first().json;
if (!b.siteId) throw new Error('siteId required');
if (!b.message) throw new Error('message required');

return [{
  json: {
    siteId: b.siteId,
    conversationId: b.conversationId || null,
    userId: b.userId || 'anonymous',
    message: b.message,
    image: b.image || null
  }
}];

const inp = $('Validate Input').item.json;
const siteArr = $input.first().json;
const site = Array.isArray(siteArr) ? siteArr[0] : siteArr;
if (!site) throw new Error('Site not found');

const repoUrl = site.repo_url || '';
const match = repoUrl.match(/github\.com\/([^/]+)\/([^/]+)/);
const owner = match ? match[1] : '';
const repo = match ? match[2].replace(/\.git$/, '') : '';

// SMART FILE SELECTION based on user intent
const msg = inp.message.toLowerCase();
const filesToFetch = [];

// Design/Style keywords → globals.css
if (msg.match(/color|theme|style|css|background|gradient|dark|light|font|design/)) {
  filesToFetch.push('src/app/globals.css');
  filesToFetch.push('tailwind.config.ts');
}

// Component keywords
if (msg.match(/header|nav|menu/)) filesToFetch.push('src/components/Header.tsx');
if (msg.match(/hero|banner/)) filesToFetch.push('src/components/Hero.tsx');
if (msg.match(/footer/)) filesToFetch.push('src/components/Footer.tsx');
if (msg.match(/product|card/)) filesToFetch.push('src/components/ProductCard.tsx');
if (msg.match(/feature/)) filesToFetch.push('src/components/Features.tsx');
if (msg.match(/newsletter|subscribe/)) filesToFetch.push('src/components/Newsletter.tsx');

// Fix/Error/Bug keywords - load related files
if (msg.match(/fix|error|broken|bug|issue|conflict|merge/)) {
  // Check if specific component mentioned
  if (msg.match(/header/)) filesToFetch.push('src/components/Header.tsx');
  else if (msg.match(/hero/)) filesToFetch.push('src/components/Hero.tsx');
  else if (msg.match(/footer/)) filesToFetch.push('src/components/Footer.tsx');
  else {
    // General fix - load main files
    filesToFetch.push('src/app/page.tsx');
    filesToFetch.push('src/app/globals.css');
  }
}

// Page/Layout keywords
if (msg.match(/page|layout|home|main|app/) || filesToFetch.length === 0) {
  if (!filesToFetch.includes('src/app/page.tsx')) filesToFetch.push('src/app/page.tsx');
}

// Limit to max 4 files
const finalFiles = [...new Set(filesToFetch)].slice(0, 4);

return [{
  json: {
    ...inp,
    site: {
      id: site.id,
      name: site.name,
      repo_url: site.repo_url,
      default_branch: site.default_branch || 'main',
      stack: site.stack || 'nextjs',
      owner,
      repo
    },
    fileContents: {},
    filesToFetch: finalFiles,
    owner,
    repo,
    branch: site.default_branch || 'main'
  }
}];

const ctx = $input.first().json;
const files = ctx.filesToFetch || [];

if (files.length === 0) {
  return [{ json: { ...ctx, fileContents: {} } }];
}

const items = files.map(f => ({
  json: {
    ...ctx,
    currentFile: f
  }
}));

return items;

const items = $input.all();
const base = items[0].json;
const fileContents = {};

for (const item of items) {
  const path = item.json.currentFile;
  const body = item.json.body;
  const statusCode = item.json.statusCode;

  if (statusCode === 200 && body) {
    // Full content - no truncation!
    fileContents[path] = typeof body === 'string' ? body : JSON.stringify(body, null, 2);
  }
}

return [{
  json: {
    siteId: base.siteId,
    conversationId: base.conversationId,
    userId: base.userId,
    message: base.message,
    image: base.image,
    site: base.site,
    owner: base.owner,
    repo: base.repo,
    branch: base.branch,
    fileContents
  }
}];

const query = $fromAI('input', 'Directory path to list, e.g. "." or "src/components"', 'string');
const ctx = $('Merge Files').item.json;
const owner = ctx.site.owner;
const repo = ctx.site.repo;
const branch = ctx.branch;

let path = '.';
try {
  if (query && query !== 'list') {
    const parsed = JSON.parse(query);
    path = parsed.input || parsed.path || '.';
  }
} catch {
  path = query || '.';
}

path = path.replace(/^\/+/, '').replace(/\/+$/, '');
if (path === '' || path === '.') path = '';

const url = `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`;

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28'
    }
  });

  let files = response.tree
    .filter(item => item.type === 'blob')
    .map(item => item.path);

  if (path) {
    files = files.filter(f => f.startsWith(path + '/') || f === path);
  }

  // Group by directory for cleaner output
  const result = files.slice(0, 50).join('\n');
  return `Files in ${path || 'repository'}:\n${result}`;
} catch (error) {
  return JSON.stringify({ error: error.message });
}

const query = $fromAI('input', 'File path to read, e.g. "src/app/page.tsx"', 'string');
const ctx = $('Merge Files').item.json;
const owner = ctx.site.owner;
const repo = ctx.site.repo;
const branch = ctx.branch;

let filePath = query;
try {
  if (query.startsWith('{')) {
    const parsed = JSON.parse(query);
    filePath = parsed.input || parsed.path || parsed.filePath || query;
  }
} catch {
  filePath = query;
}

filePath = filePath.replace(/^\/+/, '').trim();

// Check if already in context
if (ctx.fileContents && ctx.fileContents[filePath]) {
  return `File already in context. Content:\n${ctx.fileContents[filePath]}`;
}

const url = `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`;

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github.raw+json',
      'X-GitHub-Api-Version': '2022-11-28'
    }
  });

  return `Contents of ${filePath}:\n${response}`;
} catch (error) {
  return JSON.stringify({ error: `Failed to read ${filePath}: ${error.message}` });
}

const query = $fromAI('input', 'JSON with filePath and content', 'string');
const ctx = $('Merge Files').item.json;
const owner = ctx.site.owner;
const repo = ctx.site.repo;
const branch = ctx.branch;

let filePath, content;

try {
  // Handle various input formats
  let parsed;
  if (query.startsWith('{')) {
    parsed = JSON.parse(query);
  } else {
    // Try to extract from nested format
    const match = query.match(/\{.*\}/s);
    if (match) {
      parsed = JSON.parse(match[0]);
    }
  }

  if (parsed) {
    // Handle nested input format
    if (parsed.input && typeof parsed.input === 'string') {
      try {
        const inner = JSON.parse(parsed.input);
        filePath = inner.filePath;
        content = inner.content;
      } catch {
        filePath = parsed.filePath;
        content = parsed.content;
      }
    } else {
      filePath = parsed.filePath;
      content = parsed.content;
    }
  }
} catch (error) {
  return JSON.stringify({ error: 'Invalid JSON input. Expected {"filePath": "...", "content": "..."}' });
}

if (!filePath || !content) {
  return JSON.stringify({ error: 'Both filePath and content are required' });
}

filePath = filePath.replace(/^\/+/, '');

// Get current file SHA if exists
let sha = null;
try {
  const existingFile = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28'
    }
  });
  sha = existingFile.sha;
} catch (e) {
  // File doesn't exist, that's fine
}

// Create/update file
try {
  const body = {
    message: `Update ${filePath} via AutoMate`,
    content: Buffer.from(content).toString('base64'),
    branch: branch
  };

  if (sha) body.sha = sha;

  const response = await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      'Content-Type': 'application/json'
    },
    body: body
  });

  return JSON.stringify({ 
    success: true, 
    file: filePath,
    action: sha ? 'updated' : 'created',
    commit: response.commit?.sha?.substring(0, 7) || 'unknown'
  });
} catch (error) {
  return JSON.stringify({ error: `Failed to save ${filePath}: ${error.message}` });
}

const query = $fromAI('input', 'File path to delete', 'string');
const ctx = $('Merge Files').item.json;
const owner = ctx.site.owner;
const repo = ctx.site.repo;
const branch = ctx.branch;

let filePath = query;
try {
  const parsed = JSON.parse(query);
  filePath = parsed.input || parsed.path || parsed.filePath || query;
} catch {
  filePath = query;
}

filePath = filePath.replace(/^\/+/, '').trim();

// Get current file SHA
try {
  const existingFile = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json'
    }
  });

  await this.helpers.httpRequest({
    method: 'DELETE',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json'
    },
    body: {
      message: `Delete ${filePath} via AutoMate`,
      sha: existingFile.sha,
      branch: branch
    }
  });

  return JSON.stringify({ success: true, deleted: filePath });
} catch (error) {
  return JSON.stringify({ error: `Failed to delete ${filePath}: ${error.message}` });
}

const query = $fromAI('input', 'Search query', 'string');
const ctx = $('Merge Files').item.json;
const owner = ctx.site.owner;
const repo = ctx.site.repo;

let searchTerm = query;
try {
  const parsed = JSON.parse(query);
  searchTerm = parsed.input || parsed.query || query;
} catch {
  searchTerm = query;
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/search/code?q=${encodeURIComponent(searchTerm)}+repo:${owner}/${repo}`,
    headers: {
      'Authorization': `Bearer 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`,
      'Accept': 'application/vnd.github+json'
    }
  });

  if (response.items && response.items.length > 0) {
    const results = response.items.slice(0, 10).map(item => 
      `- ${item.path}`
    ).join('\n');
    return `Found "${searchTerm}" in:\n${results}`;
  } else {
    return `No results found for "${searchTerm}"`;
  }
} catch (error) {
  return JSON.stringify({ error: error.message });
}

const agentOutput = $input.first().json;
const ctx = $('Merge Files').item.json;

let response = '';
let filesChanged = [];
let success = true;

if (agentOutput.output) {
  response = agentOutput.output;
}

// Extract file changes from intermediate steps
if (agentOutput.intermediateSteps) {
  for (const step of agentOutput.intermediateSteps) {
    if (step.action?.tool === 'create_file' && step.observation) {
      try {
        const obs = JSON.parse(step.observation);
        if (obs.success && obs.file) {
          filesChanged.push(obs.file);
        }
      } catch {}
    }
  }
}

// Check for max iterations error
if (agentOutput.output?.includes('max iterations')) {
  success = false;
  response = 'The request was too complex. Please try a simpler task or be more specific.';
}

return [{
  json: {
    success,
    response,
    filesChanged,
    siteId: ctx.siteId,
    conversationId: ctx.conversationId,
    message: ctx.message
  }
}];
